  return getOffset(el);\n    }\n  },\n  isWindow: isWindow,\n  each: each,\n  css: css,\n  clone: function (obj) {\n    var ret = {};\n    for (var i in obj) {\n      ret[i] = obj[i];\n    }\n    var overflow = obj.overflow;\n    if (overflow) {\n      for (i in obj) {\n        ret.overflow[i] = obj.overflow[i];\n      }\n    }\n    return ret;\n  },\n  mix: mix,\n  scrollLeft: function (w, v) {\n    if (isWindow(w)) {\n      if (v === undefined) {\n        return getScrollLeft(w);\n      } else {\n        window.scrollTo(v, getScrollTop(w));\n      }\n    } else {\n      if (v === undefined) {\n        return w.scrollLeft;\n      } else {\n        w.scrollLeft = v;\n      }\n    }\n  },\n  scrollTop: function (w, v) {\n    if (isWindow(w)) {\n      if (v === undefined) {\n        return getScrollTop(w);\n      } else {\n        window.scrollTo(getScrollLeft(w), v);\n      }\n    } else {\n      if (v === undefined) {\n        return w.scrollTop;\n      } else {\n        w.scrollTop = v;\n      }\n    }\n  },\n  merge: function () {\n    var ret = {};\n    for (var i = 0; i < arguments.length; i++) {\n      utils.mix(ret, arguments[i]);\n    }\n    return ret;\n  },\n  viewportWidth: 0,\n  viewportHeight: 0\n};\n\nmix(utils, domUtils);\n","import React, { useState, useEffect } from 'react';\r\nimport Autocomplete from 'react-autocomplete';\r\n\r\nconst EmployeeAutocomplete = ({ options, onChange, onSelect, value }) => {\r\n    const [keyword, setKeyword] = useState(value || '');\r\n\r\n    useEffect(() => {\r\n        if (value) {\r\n            setKeyword(value);\r\n        }\r\n    }, [value]);\r\n\r\n    const handleChange = event => {\r\n        const value = event.target.value;\r\n        setKeyword(value);\r\n        onChange(value);\r\n    };\r\n\r\n    const handleSelect = (selectedKeyword, selectedItem) => {\r\n        setKeyword(selectedKeyword);\r\n        onSelect(selectedItem);\r\n    };\r\n\r\n    return (\r\n        <Autocomplete\r\n            items={options}\r\n            getItemValue={item => item.value}\r\n            wrapperProps={{ className: 'react-autocomplete-wrapper' }}\r\n            wrapperStyle={{ display: 'block' }}\r\n            renderInput={props => <input type=\"text\" name=\"Employee\" {...props} />}\r\n            renderMenu={items => <div className=\"items\" children={items} />}\r\n            renderItem={(item, isHighlighted) =>\r\n                <div className={`item ${isHighlighted ? 'highlighted' : ''}`} key={item.id}>\r\n                    {item.value}\r\n                </div>\r\n            }\r\n            inputProps={{\r\n                className: 'form-control'\r\n            }}\r\n            value={keyword}\r\n            onChange={handleChange}\r\n            onSelect={handleSelect}\r\n        />\r\n    );\r\n};\r\n\r\nexport default EmployeeAutocomplete;","import React from 'react';\r\nimport { Form, Field } from 'formik';\r\n\r\nimport Errors from '../../shared/components/Errors';\r\nimport EmployeeAutocomplete from './EmployeeAutocomplete';\r\n\r\nconst RenderFrom = ({ errors, isInternal, onChangeInternal, selectExtension, employees, onSearchEmployee, onSelectEmployee, isSubmitting, title, setSelectGroup }) => {\r\n    const handleGoBack = () => {\r\n        history.back();\r\n    };\r\n\r\n    const handleSelectGroup = event => {\r\n        setSelectGroup(event.target.value);\r\n    }\r\n\r\n    return (\r\n        <div className=\"card\">\r\n            <Errors errors={errors} />\r\n            <Form className=\"form-horizontal\">\r\n                <input name=\"EmpId\" hidden />\r\n                <div className=\"form-group\">\r\n                    <div className=\"label-form\">\r\n                        <label className=\"control-label\">Is Internal</label>\r\n                    </div>\r\n                    <div className=\"input-form\">\r\n                        <Field name=\"IsInternal\" className=\"form-control\">\r\n                            {({\r\n                                field\r\n                            }) => (\r\n                                <input\r\n                                    checked={isInternal}\r\n                                    type=\"checkbox\"\r\n                                    {...field}\r\n                                    onChange={onChangeInternal}\r\n                                />\r\n                            )}\r\n                        </Field>\r\n                    </div>\r\n                </div>\r\n                <div className=\"form-group\">\r\n                    <div className=\"label-form\">\r\n                        <label className=\"control-label\">Group</label>\r\n                    </div>\r\n                    <div className=\"input-form\">\r\n                        <Field as=\"select\" name=\"TeamId\" className=\"form-control\" onChange={handleSelectGroup}>\r\n                            {\r\n                                selectExtension && selectExtension.map(item => (\r\n                                    <option defaultValue={item.value} value={item.value} key={item.value}>{item.text}</option>\r\n                                ))\r\n                            }\r\n                        </Field>\r\n                    </div>\r\n                </div>\r\n                {\r\n                    isInternal && <div className=\"form-group\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Employee</label>\r\n                        </div>\r\n                        <div className=\"select-form\">\r\n                            <Field type=\"text\" name=\"Employee\" className=\"form-control\">\r\n                                {() => (\r\n                                    <EmployeeAutocomplete\r\n                                        options={employees}\r\n                                        onChange={onSearchEmployee}\r\n                                        onSelect={onSelectEmployee}\r\n                                    />\r\n                                )}\r\n                            </Field>\r\n                        </div>\r\n                    </div>\r\n                }\r\n\r\n                <div className=\"form-group\">\r\n                    <div className=\"label-form\">\r\n                        <label className=\"control-label\">Full Name</label>\r\n                    </div>\r\n                    <div className=\"input-form\">\r\n                        <Field name=\"FullName\">\r\n                            {({\r\n                                field\r\n                            }) => (\r\n                                <input\r\n                                    autoComplete='off'\r\n                                    className=\"form-control\"\r\n                                    type=\"text\"\r\n                                    {...field}\r\n                                    readOnly={isInternal || false}\r\n                                />\r\n                            )}\r\n                        </Field>\r\n                    </div>\r\n                </div>\r\n                <div className=\"form-group\">\r\n                    <div className=\"label-form\">\r\n                        <label className=\"control-label\">Nickname</label>\r\n                    </div>\r\n                    <div className=\"input-form\">\r\n                        <Field name=\"NickName\" className=\"form-control\">\r\n                            {({\r\n                                field\r\n                            }) => (\r\n                                <input\r\n                                    autoComplete='off'\r\n                                    className=\"form-control\"\r\n                                    type=\"text\"\r\n                                    {...field}\r\n                                    readOnly={isInternal || false}\r\n                                />\r\n                            )}\r\n                        </Field>\r\n                    </div>\r\n                </div>\r\n                <div className=\"form-group\">\r\n                    <div className=\"label-form\">\r\n                        <label className=\"control-label\">Extension No</label>\r\n                    </div>\r\n                    <div className=\"input-form\">\r\n                        <Field type=\"text\" name=\"ExtensionNo\" className=\"form-control\" autoComplete='off' />\r\n                    </div>\r\n                </div>\r\n                <div className=\"form-group\">\r\n                    <button type=\"submit\" id=\"btnSubmit\" className=\"btn btn-primary\" disabled={isSubmitting} style={{ marginRight: \"5px\" }}>{title}</button>\r\n                    <a className=\"btn btn-default\" onClick={handleGoBack}>Back</a>\r\n                </div>\r\n            </Form>\r\n        </div>\r\n    );\r\n};\r\n\r\nexport default RenderFrom;","import React from 'react';\r\nimport ReactDOM from 'react-dom';\r\nimport AppContainer from './components/AppContainer';\r\n\r\n\r\nReactDOM.render(\r\n    <AppContainer />,\r\n    document.getElementById(\"edit-extension-no\")\r\n);","import 'jquery-ui-bundle/jquery-ui';\r\nimport React, { useEffect, useState } from 'react';\r\nimport * as Yup from 'yup';\r\nimport axios from 'axios';\r\nimport toastr from 'toastr';\r\nimport { Formik } from 'formik';\r\n\r\nimport RenderForm from '../../RenderForm';\r\n\r\nimport { axiosError, resolveClientUrl, toastOptions } from '../../../../shared/common.functions';\r\n\r\nconst AppContainer = () => {\r\n    const [extensionDetail, setExtensionDetail] = useState(null);\r\n    const [selectExtension, setSelectExtension] = useState(null);\r\n    const [isInternal, setIsInternal] = useState(window.isInternal === 'True');\r\n    const [employees, setEmployees] = useState([]);\r\n    const [selectEmployee, setSelectEmployee] = useState(null);\r\n    const [selectGroup, setSelectGroup] = useState('');\r\n\r\n    const editExtensionSchema = Yup.object({\r\n        ExtensionNo: Yup.string()\r\n            .trim()\r\n            .required('Extension No field is required!'),\r\n        Employee: isInternal && extensionDetail && extensionDetail.empId === 0 ? Yup.string()\r\n            .trim()\r\n            .required('Employee field is required!') : false,\r\n    });\r\n\r\n    const getExtentionById = (isInternal, id) => {\r\n        axios({\r\n            url: resolveClientUrl('ExtensionNo/GetExtenstionById'),\r\n            method: 'GET',\r\n            headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n            params: {\r\n                id: id,\r\n                isInternal: isInternal\r\n            }\r\n        }).then(response => {\r\n            setExtensionDetail(response.data);\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    const getEmployees = query => {\r\n        if (query.trim().length >= 2) {\r\n            axios({\r\n                url: resolveClientUrl('employee/getemployees'),\r\n                method: 'GET',\r\n                headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n                params: { query }\r\n            }).then(response => {\r\n                const { data } = response;\r\n                const employeeOptions = data.map(item => {\r\n                    return {\r\n                        id: item.Id,\r\n                        value: `${item.NickName} (${item.FullName})`,\r\n                        fullName: item.FullName,\r\n                        nickName: item.NickName\r\n                    };\r\n                });\r\n\r\n                setEmployees(employeeOptions);\r\n            }).catch(axiosError);\r\n        } else {\r\n            setEmployees([]);\r\n        }\r\n    };\r\n\r\n    const getGroupExtension = isInternal => {\r\n        axios({\r\n            url: resolveClientUrl('ExtensionNo/GetGroupExtension'),\r\n            method: 'GET',\r\n            headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n            params: { isInternal }\r\n        }).then(response => {\r\n            setSelectExtension(response.data);\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    const handleSelectEmployee = selectedItem => {\r\n        setSelectEmployee(selectedItem);\r\n    };\r\n\r\n    useEffect(() => {\r\n        getExtentionById(window.isInternal, window.id);\r\n    }, [window.isInternal, window.id]);\r\n\r\n    useEffect(() => {\r\n        getGroupExtension(isInternal);\r\n    }, []);\r\n\r\n    const handleChangeInternal = event => {\r\n        setIsInternal(event.target.checked);\r\n        axios({\r\n            url: resolveClientUrl('ExtensionNo/GetGroupExtension'),\r\n            method: 'GET',\r\n            headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n            params: { isInternal: event.target.checked }\r\n        }).then(response => {\r\n            setSelectExtension(response.data);\r\n            setExtensionDetail({\r\n                empId: extensionDetail.empId,\r\n                teamId: response.data[0].value,\r\n                extensionNo: extensionDetail.extensionNo,\r\n                nickName: extensionDetail.nickName,\r\n                fullName: extensionDetail.fullName,\r\n                employeeExtensionId: extensionDetail.employeeExtensionId,\r\n                employee: extensionDetail.employee\r\n            });\r\n            setSelectGroup(response.data[0].value);\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    const handleSubmit = (values, { setSubmitting }) => {\r\n        setSubmitting(true);\r\n        const model = {\r\n            fullName: values.FullName,\r\n            nickName: values.NickName,\r\n            extensionNo: values.ExtensionNo,\r\n            isInternal: values.IsInternal,\r\n            empId: isNaN(parseInt(values.EmpId, 10)) ? 0 : values.EmpId,\r\n            employeeExtensionId: extensionDetail.employeeExtensionId,\r\n            teamId: values.TeamId\r\n        };\r\n        axios({\r\n            method: 'POST',\r\n            url: resolveClientUrl('ExtensionNo/Edit'),\r\n            headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n            data: model\r\n        }).then(response => {\r\n            const { data } = response;\r\n            if (data.isSuccessful) {\r\n                toastr.success('Updated successfully!', '', toastOptions());\r\n                setTimeout(function () {\r\n                    document.location = resolveClientUrl('ExtensionNo/Index');\r\n                }, 3000);\r\n            } else {\r\n                toastr.error(data.message, '', toastOptions());\r\n                setSubmitting(false);\r\n            }\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    if (extensionDetail == null) {\r\n        return null;\r\n    };\r\n    const empId = selectEmployee && selectEmployee.id || extensionDetail.empId;\r\n    const emPloyee = selectEmployee && selectEmployee.value || '';\r\n    const fullName = selectEmployee && selectEmployee.fullName || extensionDetail.fullName || '';\r\n    const teamId = selectGroup || extensionDetail.teamId;\r\n    const nickName = selectEmployee && selectEmployee.nickName || extensionDetail.nickName || '';\r\n    const extensionNo = extensionDetail.extensionNo || '';\r\n\r\n    return (\r\n        <Formik\r\n            validateOnBlur={false}\r\n            validateOnChange={false}\r\n            initialValues={{\r\n                EmpId: empId,\r\n                Employee: emPloyee,\r\n                FullName: fullName,\r\n                TeamId: teamId,\r\n                NickName: nickName,\r\n                ExtensionNo: extensionNo,\r\n                IsInternal: isInternal\r\n            }}\r\n            enableReinitialize={true}\r\n            validationSchema={editExtensionSchema}\r\n            onSubmit={handleSubmit}\r\n        >\r\n            {({ errors, isSubmitting }) => (\r\n                <RenderForm\r\n                    errors={errors}\r\n                    isInternal={isInternal}\r\n                    onChangeInternal={handleChangeInternal}\r\n                    selectExtension={selectExtension}\r\n                    employees={employees}\r\n                    onSearchEmployee={getEmployees}\r\n                    onSelectEmployee={handleSelectEmployee}\r\n                    isSubmitting={isSubmitting}\r\n                    setSelectGroup={setSelectGroup}\r\n                    title='Update'\r\n                />\r\n            )}\r\n        </Formik>\r\n    );\r\n};\r\n\r\nexport default AppContainer;"],"sourceRoot":""}
